"""Green-Screen-Memes freistellen: einmalig als WebM mit echtem Alphakanal, nie live beim Abspielen.

Ganzer Ordner: ``.venv\\Scripts\\python greenscreen.py`` (Standard: ``memes/``).
Hochgeladene Videos mit Haken „Green Screen entfernen“ stellt der laufende Server mit derselben
Funktion ``process_file`` frei.
"""

import argparse
import logging
import os
import sys
from collections.abc import Callable
from concurrent.futures import ProcessPoolExecutor, as_completed
from fractions import Fraction
from pathlib import Path

import av
import cv2
import numpy as np
import psutil

log = logging.getLogger(__name__)

VIDEO_EXT = (".mp4", ".mov", ".m4v", ".webm", ".mkv")
WORKERS = 3
# Ein echter Green Screen hat am Rand deutlich mehr Grün als Rot und Blau, und zwar fast überall.
MIN_STRENGTH = 60
MIN_BORDER = 0.6
PROBE_FRAMES = 30
# Niedriger als beim Massenimport früher: die Quelle soll sichtbar unverändert bleiben.
CRF = "26"


class KeyingError(Exception):
    """Freistellen fehlgeschlagen; das Original bleibt unangetastet."""


def _border(bgr: np.ndarray) -> np.ndarray:
    return np.concatenate([bgr[:8].reshape(-1, 3), bgr[-8:].reshape(-1, 3),
                           bgr[:, :8].reshape(-1, 3), bgr[:, -8:].reshape(-1, 3)])


def key_color(bgr: np.ndarray) -> np.ndarray:
    """Hintergrundgrün, gemessen am Bildrand; jedes Video hat ein anderes Grün."""
    return np.median(_border(bgr), axis=0).astype(np.float32)


def green_key(src: Path) -> np.ndarray | None:
    """Hintergrundgrün, falls das Video einen Green Screen hat, sonst None."""
    try:
        with av.open(str(src)) as probe:
            if not probe.streams.video:
                return None
            # Mehrere Bilder prüfen, weil viele Memes mit einer Abblende oder einem Titel beginnen.
            for i, frame in enumerate(probe.decode(video=0)):
                if i >= PROBE_FRAMES:
                    break
                bgr = frame.to_ndarray(format="bgr24")
                key = key_color(bgr)
                if key[1] - max(key[0], key[2]) < MIN_STRENGTH:
                    continue
                near = np.abs(_border(bgr).astype(np.float32) - key).max(axis=1) < 40
                if near.mean() >= MIN_BORDER:
                    return key
    except (av.FFmpegError, ValueError):
        pass
    return None


def has_alpha(path: Path) -> bool:
    """WebM, dessen Videospur als transparent markiert ist (so schreibt es ``convert``)."""
    if path.suffix.lower() != ".webm":
        return False
    try:
        with av.open(str(path)) as probe:
            meta = probe.streams.video[0].metadata if probe.streams.video else {}
    except (av.FFmpegError, ValueError):
        return False
    return any(k.lower() == "alpha_mode" and v == "1" for k, v in meta.items())


def matte(bgr: np.ndarray, key: np.ndarray) -> np.ndarray:
    strength = max(1.0, float(key[1] - max(key[0], key[2])))
    px = bgr.astype(np.int16)
    excess = (px[..., 1] - np.maximum(px[..., 0], px[..., 2])).astype(np.float32)
    # Mischpixel an Kanten haben anteilig Grünüberschuss, daraus ergibt sich ein weicher Übergang.
    alpha = 1 - np.clip((excess - 0.2 * strength) / (0.6 * strength), 0, 1)
    alpha[alpha < 0.04] = 0
    alpha[alpha > 0.96] = 1
    return alpha


def cutout(bgr: np.ndarray, key: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """Freigestellte Farben und Alpha; grüner Schimmer an Kanten wird neutralisiert."""
    alpha = matte(bgr, key)
    px = bgr.astype(np.float32)
    # Halbtransparente Kantenpixel enthalten anteilig Hintergrundgrün; herausgerechnet bleibt kein Saum.
    soft = (alpha > 0) & (alpha < 1)
    a = np.maximum(alpha[soft], 0.15)[:, None]
    px[soft] = np.clip((px[soft] - (1 - a) * key) / a, 0, 255)
    other = np.maximum(px[..., 0], px[..., 2])
    # Nur nahe der Kante entfärben, damit echtes Grün im Motiv (Kleidung, Logos) erhalten bleibt.
    edge = cv2.dilate((alpha < 0.99).astype(np.uint8), np.ones((7, 7), np.uint8)).astype(bool)
    px[..., 1] = np.where(edge, np.minimum(px[..., 1], other), px[..., 1])
    # Viele Quellen tragen einen hellen, nicht grünen Schein ums Motiv; daher die Kante leicht einziehen.
    alpha = cv2.GaussianBlur(cv2.erode(alpha, np.ones((3, 3), np.uint8), iterations=2), (3, 3), 0)
    alpha[alpha < 0.04] = 0
    px[alpha == 0] = 0
    return px, alpha


def content_box(src: Path, key: np.ndarray) -> tuple[int, int, int, int]:
    """Kleinstes Rechteck, in dem über das ganze Video etwas Sichtbares liegt."""
    seen = None
    with av.open(str(src)) as box:
        for i, frame in enumerate(box.decode(video=0)):
            if i % 3:
                continue
            small = cv2.resize(frame.to_ndarray(format="bgr24"), None, fx=0.25, fy=0.25,
                               interpolation=cv2.INTER_AREA)
            mask = matte(small, key) > 0.5
            seen = mask if seen is None else seen | mask
            h, w = frame.height, frame.width
    ys, xs = np.nonzero(seen)
    if not len(xs):
        return 0, 0, w, h
    pad = 12
    x0, y0 = max(0, xs.min() * 4 - pad), max(0, ys.min() * 4 - pad)
    x1, y1 = min(w, xs.max() * 4 + 4 + pad), min(h, ys.max() * 4 + 4 + pad)
    # yuva420p braucht gerade Kantenlängen und Ursprünge.
    return int(x0) // 2 * 2, int(y0) // 2 * 2, int(x1) // 2 * 2, int(y1) // 2 * 2


def _frames(stream) -> int:
    if stream.frames:
        return stream.frames
    if stream.duration and stream.time_base and stream.average_rate:
        return int(stream.duration * stream.time_base * stream.average_rate)
    return 0


def convert(src: Path, dst: Path, key: np.ndarray, threads: int = 4,
            progress: Callable[[float], None] | None = None) -> None:
    """Grünes Video zu WebM (VP9 mit echtem Alphakanal, Ton als Opus) in Originalauflösung."""
    x0, y0, x1, y1 = content_box(src, key)
    with av.open(str(src)) as inp, av.open(str(dst), "w", format="webm") as out:
        vin = inp.streams.video[0]
        ain = inp.streams.audio[0] if inp.streams.audio else None
        fps = vin.average_rate or Fraction(30)
        total = _frames(vin)
        vout = out.add_stream("libvpx-vp9", rate=fps)
        vout.width, vout.height, vout.pix_fmt = x1 - x0, y1 - y0, "yuva420p"
        vout.options = {"crf": CRF, "b": "0", "deadline": "good", "cpu-used": "4", "row-mt": "1",
                        "tile-columns": "2", "auto-alt-ref": "0"}
        vout.thread_count = threads
        # Ohne diese Markierung zeigen Browser die Alphaebene nicht an.
        vout.metadata["alpha_mode"] = "1"
        aout = out.add_stream("libopus", rate=48000, layout="stereo") if ain else None
        index = 0
        for packet in inp.demux(*[s for s in (vin, ain) if s]):
            for frame in packet.decode():
                if packet.stream is vin:
                    rgb, alpha = cutout(frame.to_ndarray(format="bgr24")[y0:y1, x0:x1], key)
                    bgra = np.dstack([rgb, alpha * 255]).round().astype(np.uint8)
                    out_frame = av.VideoFrame.from_ndarray(bgra, format="bgra").reformat(format="yuva420p")
                    out_frame.pts, out_frame.time_base = index, 1 / fps
                    index += 1
                    out.mux(vout.encode(out_frame))
                    if progress and total and index % 15 == 0:
                        progress(min(0.99, index / total))
                else:
                    frame.pts = None
                    out.mux(aout.encode(frame))
        out.mux(vout.encode(None))
        if aout:
            out.mux(aout.encode(None))


def _alpha_plane(frame) -> np.ndarray:
    plane = frame.planes[3]
    raw = np.frombuffer(bytes(plane), np.uint8).reshape(-1, plane.line_size)
    return raw[:frame.height, :frame.width]


def validate(src: Path, dst: Path) -> None:
    """Prüft das Ergebnis wirklich dekodiert: Alphakanal, Transparenz, Länge und Ton."""
    with av.open(str(src)) as s:
        want = sum(1 for _ in s.demux(s.streams.video[0]) if _.size)
        src_audio = bool(s.streams.audio)
    if not has_alpha(dst):
        raise KeyingError("Ergebnis ist nicht als transparent markiert")
    # Der eingebaute vp9-Decoder verwirft die Alphaebene; nur libvpx liefert sie.
    dec = av.CodecContext.create("libvpx-vp9", "r")
    count, clear, solid = 0, False, False
    with av.open(str(dst)) as d:
        if src_audio and not d.streams.audio:
            raise KeyingError("Ton fehlt im Ergebnis")
        for packet in d.demux(d.streams.video[0]):
            if not packet.size:
                continue
            count += 1
            if clear and solid:
                continue
            for frame in dec.decode(packet):
                if frame.format.name != "yuva420p":
                    raise KeyingError(f"Ergebnis hat keinen Alphakanal ({frame.format.name})")
                alpha = _alpha_plane(frame)
                clear = clear or bool((alpha < 16).any())
                solid = solid or bool((alpha > 240).any())
    if count < want * 0.9:
        raise KeyingError(f"Ergebnis zu kurz ({count} von {want} Bildern)")
    if not (clear and solid):
        raise KeyingError("Ergebnis ist nicht teilweise transparent")


def process_file(src: Path, threads: int = 4, progress: Callable[[float], None] | None = None) -> Path | None:
    """Stellt ein Video frei und ersetzt das Original erst nach erfolgreicher Prüfung.

    Rückgabe: Pfad des freigestellten WebM, oder None, wenn das Video keinen Green Screen hat.
    """
    final = src.with_suffix(".webm")
    if has_alpha(src):
        return src
    # Abbruch zwischen Ersetzen und Löschen beim letzten Lauf: fertiges Ergebnis prüfen, dann aufräumen.
    if final != src and final.exists() and has_alpha(final):
        validate(src, final)
        src.unlink()
        return final
    key = green_key(src)
    if key is None:
        return None
    # Führender Punkt: die Ordnerüberwachung ignoriert die halbfertige Datei.
    tmp = src.with_name(f".{src.stem}.keying.webm")
    try:
        convert(src, tmp, key, threads, progress)
        validate(src, tmp)
        os.replace(tmp, final)
    except Exception as exc:
        tmp.unlink(missing_ok=True)
        if isinstance(exc, KeyingError):
            raise
        raise KeyingError(str(exc) or type(exc).__name__) from exc
    if final != src:
        src.unlink()
    return final


def low_priority() -> None:
    """Freistellen soll Tracking und Bühne nie ausbremsen."""
    psutil.Process().nice(psutil.BELOW_NORMAL_PRIORITY_CLASS if sys.platform == "win32" else 10)


def _worker(src: str) -> tuple[str, str]:
    low_priority()
    path = Path(src)
    if has_alpha(path):
        return "skip", "schon freigestellt"
    try:
        out = process_file(path, threads=2)
    except KeyingError as exc:
        return "error", str(exc)
    if out is None:
        return "skip", "kein Green Screen erkannt, bleibt unverändert"
    return "ok", out.name


def process_folder(folder: Path, workers: int = WORKERS) -> tuple[int, int, int]:
    """Alle Videos im Ordner freistellen. Rückgabe: (freigestellt, übersprungen, Fehler)."""
    files = sorted(p for p in folder.iterdir()
                   if p.is_file() and p.suffix.lower() in VIDEO_EXT and not p.name.startswith("."))
    todo = [p for p in files if not has_alpha(p)]
    skipped = len(files) - len(todo)
    print(f"{len(files)} Videos in {folder}, {skipped} schon freigestellt, {len(todo)} zu prüfen.",
          flush=True)
    done = errors = 0
    with ProcessPoolExecutor(workers) as pool:
        futures = {pool.submit(_worker, str(p)): p for p in todo}
        for i, future in enumerate(as_completed(futures), 1):
            name = futures[future].name
            try:
                status, info = future.result()
            except Exception as exc:
                status, info = "error", str(exc) or type(exc).__name__
            if status == "ok":
                done += 1
                print(f"[{i}/{len(todo)}] OK      {name} -> {info}", flush=True)
            elif status == "skip":
                skipped += 1
                print(f"[{i}/{len(todo)}] SKIP    {name}: {info}", flush=True)
            else:
                errors += 1
                print(f"[{i}/{len(todo)}] FEHLER  {name}: {info} (Original bleibt)", flush=True)
    return done, skipped, errors


def main(argv: list[str] | None = None) -> int:
    from .server import MEMES_DIR

    parser = argparse.ArgumentParser(description="Green Screen aus allen Meme-Videos entfernen.")
    parser.add_argument("folder", type=Path, nargs="?", default=MEMES_DIR, help="Meme-Ordner")
    parser.add_argument("--workers", type=int, default=WORKERS, help="Videos gleichzeitig")
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        print(f"Ordner {args.folder} nicht gefunden.")
        return 1
    done, skipped, errors = process_folder(args.folder, args.workers)
    print(f"Fertig: {done} freigestellt, {skipped} übersprungen, {errors} Fehler.")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
